    /**
     * Method to retrieve the Campaign via CampaignFetchOneSummary
     * @param 	summary CampaignFetchOneSummary 
     * @return 	CampaignFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Campaign getCampaign( CampaignFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CampaignFetchOneSummary arg cannot be null" );
    	
    	Campaign entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Campaign
        	// --------------------------------------
        	CompletableFuture<Campaign> futureEntity = queryGateway.query(new FindCampaignQuery( new LoadCampaignFilter( summary.getCampaignId() ) ), ResponseTypes.instanceOf(Campaign.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Campaign with id " + summary.getCampaignId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


